using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;

namespace OrdersService.Models
{
    public class Order
    {
        // generated by sql server
        public int Id { get; set; }

        [Range(1, int.MaxValue, ErrorMessage = "ProductId must be at least 1.")]
        public int ProductId { get; set; }

        [Range(1, int.MaxValue, ErrorMessage = "Quantity must be at least 1.")]
        public int Quantity { get; set; }

        public DateTime DateCreated { get; set; }

        // One of the OrderStatus constants. Concurrency token: a status change only
        // saves if the status is still what we read (backstop against racing transitions).
        [ConcurrencyCheck]
        public string Status { get; set; } = string.Empty;

        // Sent by the client in the Idempotency-Key header; unique, so the same
        // submission can only ever create one order.
        [JsonIgnore]
        [MaxLength(100)]
        public string? IdempotencyKey { get; set; }

        // Identifies this order's stock return to InventoryService. Created on the first
        // cancel request and never changed, so stock is returned at most once per order.
        public Guid? CancellationId { get; set; }

        public DateTime? CancellationRequestedAt { get; set; }

        public int CancellationAttempts { get; set; }

        // true = a stock-return request may have reached InventoryService but we don't know
        // the result (timeout, 5xx, or we crashed mid-call). Such a cancellation cannot be undone.
        public bool CancellationInDoubt { get; set; }

        public DateTime? CancelledAt { get; set; }
    }
}
